"""Report languages: English by default, French on request. Kernel messages are translated by code."""

import os

LANGS = ("en", "fr")


def default_lang():
    """English unless PRINCIPALLOOP_LANG=fr (or --lang fr) asks for French."""
    chosen = os.environ.get("PRINCIPALLOOP_LANG", "").strip().lower()
    return chosen if chosen in LANGS else "en"


